const shows = $input.all().map(i => i.json);
const directShows = shows.filter(s => s.hostEmail && !s.isPlatformRelayEmail);
return directShows.map(s => ({
  json: {
    podcastName: s.podcastName,
    hostAuthor: s.hostAuthor,
    hostEmail: s.hostEmail,
    daysSinceLastEpisode: s.daysSinceLastEpisode,
    sponsorDomainsDetected: s.sponsorDomainsDetected || [],
    websiteUrl: s.websiteUrl,
    agentSummary: s.agentSummary
  }
}));
